import{_ as i,o as e,c as l,at as s}from"./chunks/framework.CY22Hent.js";const o="/assets/blog_2025-11-21_164059_918.B4p5A0hk.png",b=JSON.parse('{"title":"shuyx-admin-services项目笔记","description":"","frontmatter":{"title":"shuyx-admin-services项目笔记","date":"2024-01-04T00:00:00.000Z","lastUpdated":"2025-09-27T00:00:00.000Z","categories":["个人项目"],"tags":["个人项目"]},"headers":[],"relativePath":"blogs/个人项目/shuyx-admin-services项目笔记.md","filePath":"blogs/个人项目/shuyx-admin-services项目笔记.md"}'),t={name:"blogs/个人项目/shuyx-admin-services项目笔记.md"};function r(n,a,u,d,p,c){return e(),l("div",null,[...a[0]||(a[0]=[s('<p>[toc]</p><h1 id="shuyx-admin-services项目笔记" tabindex="-1">shuyx-admin-services项目笔记 <a class="header-anchor" href="#shuyx-admin-services项目笔记" aria-label="Permalink to &quot;shuyx-admin-services项目笔记&quot;">​</a></h1><h2 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h2><p>shuyx-admin-services 是自己搭建的后台管理系统的项目。</p><p>shuyx-admin-services 是一款功能完备的个人数据管理后台系统，专为开发者和个人用户设计，旨在提供一个统一、高效的数据管理解决方案。</p><p>该系统采用现代化架构，支持多类型数据的集中管理、存储与分析，帮助用户轻松掌控个人数字资产。</p><blockquote><p>核心功能</p></blockquote><ul><li>多应用数据管理：统一管理您的各类应用数据，包括Web应用、微信小程序、移动应用等多种平台的数据。</li><li>数据可视化：提供直观的数据报表与可视化界面，帮助您快速理解和分析数据趋势</li><li>API接口服务：内置完善的RESTful API接口，支持与其他系统无缝集成。</li><li>用户权限控制：精细的权限管理机制，确保数据安全与隐私保护。</li><li>数据备份与恢复：自动化的数据备份策略，保障数据安全可靠。</li></ul><blockquote><p>技术架构</p></blockquote><p>shuyx-admin-services 项目工程采用前后端分离架构设计，后端基于现代化Web框架开发，确保系统的高性能、可扩展性与安全性；前端则配套使用独立的 shuyx-admin-ui 项目，提供友好、直观的操作界面，两者协同工作，为用户带来流畅的使用体验。</p><blockquote><p>应用场景</p></blockquote><p>该系统特别适合需要集中管理个人项目数据的开发者、需要统一管理多平台数据的内容创作者，以及希望搭建个人数据中心的技术爱好者。</p><p>无论您是管理个人博客、微信小程序还是其他数字产品，shuyx-admin-services 都能为您提供强大的后台支持。</p><blockquote><p>配套前端</p></blockquote><p>shuyx-admin-services 项目配套的前端是shuyx-admin-ui 项目。</p><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><p>该项目技术栈采用的是Spring Cloud Alibaba 微服务框架。下面各个技术使用的具体版本信息。</p><ul><li>JDK版本8。JDK发行商选择Microsoft-OpenJDK,可以免费使用。</li><li>Spring Boot 2.7.13</li><li>Spring Cloud 2021.0.5</li><li>Spring Cloud Alibaba 框架 2.2.8 <ul><li>nacos 微服务组件 2.2.8</li><li>sentinel 流量控制组件 1.8.4</li><li>seata 分布式事务组件 1.4.2</li></ul></li></ul><h2 id="开发工具" tabindex="-1">开发工具 <a class="header-anchor" href="#开发工具" aria-label="Permalink to &quot;开发工具&quot;">​</a></h2><ul><li>IDEA 项目代码编辑器</li><li>DBeaver 数据库工具</li><li>Postman 接口测试工具</li><li>Git 版本控制工具</li></ul><h2 id="工程搭建" tabindex="-1">工程搭建 <a class="header-anchor" href="#工程搭建" aria-label="Permalink to &quot;工程搭建&quot;">​</a></h2><p>该工程的架构模式为模块化单体架构，工程采用maven的聚合父子工程的方式进行搭建。</p><p>具体参考这篇文章 <a href="/blogs/SpringCloudAlibaba/SpringCloudAlibaba笔记-版本2.2.8.html">Spring Cloud Alibaba笔记-版本2.2.8 笔记</a></p><h2 id="表的设计" tabindex="-1">表的设计 <a class="header-anchor" href="#表的设计" aria-label="Permalink to &quot;表的设计&quot;">​</a></h2><p>目前现有的表如图所示 <img src="'+o+'" alt="blog_2025-11-21_164059_918.png" loading="lazy"></p>',25)])])}const m=i(t,[["render",r]]);export{b as __pageData,m as default};
